public void mergeOnLogin(String guestId, long userId) {
    String lockKey = "cart:merge:" + userId;
    if (!lock.tryLock(lockKey, 3, TimeUnit.SECONDS)) return;
    try {
        Map<Long, Integer> guest = redis.hgetAll("cart:guest:" + guestId);
        if (guest.isEmpty()) return;                       // 已合并过
        for (var e : guest.entrySet()) {
            int merged = redis.hget("cart:user:" + userId, e.getKey()) + e.getValue();
            int limit = Math.min(stockService.available(e.getKey()), purchaseLimit(e.getKey()));
            redis.hset("cart:user:" + userId, e.getKey(), Math.min(merged, limit));
        }
        redis.del("cart:guest:" + guestId);               // 合并后立即删除，防重复
    } finally { lock.unlock(lockKey); }
}

// 发红包时预生成金额（单位：分）
List<Long> split(long totalCent, int n) {
    List<Long> res = new ArrayList<>(); long remain = totalCent;
    for (int i = n; i > 1; i--) {
        long max = remain / i * 2 - 1;                         // 二倍均值
        long amt = 1 + ThreadLocalRandom.current().nextLong(Math.max(1, max));
        res.add(amt); remain -= amt;
    }
    res.add(remain);                                           // 最后一个拿剩余，保证守恒
    return res;
}
